<script setup>
import {computed,onBeforeUnmount,onMounted,ref} from 'vue'
import {Bell,ChatDotRound,CoffeeCup,Medal,MostlyCloudy,Timer,CircleCheck,ArrowRight} from '@element-plus/icons-vue'
import {ElMessage} from 'element-plus'
import api,{errorText,unwrap} from '../api';import{useAuthStore}from'../store'
const auth=useAuthStore(),care=ref({messages:[],praise:[],users:[],actions:[],emotion:null}),dialog=ref(''),chatText=ref(''),praiseText=ref(''),selectedUserId=ref(null),focusSeconds=ref(1500),focusRunning=ref(false);let timer
const today=new Date().toISOString().slice(0,10),moods=['开心','平静','疲惫','焦虑','其他']
const apprentices=computed(()=>care.value.users.filter(u=>u.role==='apprentice')),counterpart=computed(()=>auth.user?.role==='mentor'?care.value.users.find(u=>u.id===Number(selectedUserId.value)):care.value.users.find(u=>u.id===auth.user?.mentorId))
const messages=computed(()=>care.value.messages.filter(m=>counterpart.value&&((m.fromId===auth.user.id&&m.toId===counterpart.value.id)||(m.toId===auth.user.id&&m.fromId===counterpart.value.id))).sort((a,b)=>String(a.time).localeCompare(String(b.time))))
const health=computed(()=>care.value.actions.filter(a=>a.type==='health'&&a.date===today).at(-1)),warningDone=computed(()=>care.value.actions.some(a=>a.type==='warning-handled'&&a.date===today)),focusText=computed(()=>`${String(Math.floor(focusSeconds.value/60)).padStart(2,'0')}:${String(focusSeconds.value%60).padStart(2,'0')}`)
const completed=computed(()=>[health.value,care.value.emotion,warningDone.value,care.value.praise.length].filter(Boolean).length)
const cards=computed(()=>[
 {id:'daily',name:'每日关怀',desc:'今日3项任务，注意天气变化与作业节奏。',icon:MostlyCloudy,state:'ready',status:'今日提示',action:'查看详情'},
 {id:'health',name:'健康打卡',desc:health.value?`已记录：${health.value.value}`:'记录身体状态，为工作安排提供参考。',icon:CoffeeCup,state:health.value?'done':'pending',status:health.value?'今日已打卡':'等待打卡',action:health.value?'更新状态':'立即打卡'},
 {id:'emotion',name:'情绪打卡',desc:care.value.emotion?`今日感受：${care.value.emotion.mood}`:'用一个词记录此刻状态，每天限一次。',icon:ChatDotRound,state:care.value.emotion?'done':'pending',status:care.value.emotion?'今日已完成':'等待打卡',action:care.value.emotion?'查看记录':'开始打卡'},
 {id:'praise',name:'表扬卡',desc:`已沉淀 ${care.value.praise.length} 条正向反馈。`,icon:Medal,state:'ready',status:`${care.value.praise.length} 条反馈`,action:'发送表扬'},
 {id:'focus',name:'番茄专注',desc:focusRunning.value?`本轮剩余 ${focusText.value}`:'开启25分钟免打扰专注，完成后自动留痕。',icon:Timer,state:focusRunning.value?'active':'ready',status:focusRunning.value?'进行中':'随时可用',action:focusRunning.value?'暂停专注':'开始专注'},
 {id:'warning',name:'关怀提醒',desc:warningDone.value?'已联系学员并完成今日跟进':'赵六周报尚未提交，建议了解阻碍。',icon:Bell,state:warningDone.value?'done':'alert',status:warningDone.value?'今日已处理':'1项待处理',action:warningDone.value?'查看记录':'立即处理'}])
async function load(){care.value=unwrap(await api.get('/care'));selectedUserId.value||=auth.user?.role==='mentor'?(apprentices.value[0]?.id||1):auth.user?.mentorId}
async function action(type,value){try{await api.post('/care/action',{type,value});await load();ElMessage.success('状态已记录');dialog.value=''}catch(e){ElMessage.error(errorText(e))}}
async function mood(value){try{await api.post('/care/emotion',{mood:value});await load();dialog.value='';ElMessage.success('今日情绪已记录')}catch(e){ElMessage.warning(errorText(e))}}
async function sendMessage(){if(!chatText.value.trim())return;await api.post('/care/message',{toId:counterpart.value.id,content:chatText.value});chatText.value='';await load()}
async function sendPraise(){if(!praiseText.value.trim())return ElMessage.warning('请填写具体表扬内容');await api.post('/care/praise',{toId:counterpart.value.id,content:praiseText.value,style:'薪火橙'});praiseText.value='';dialog.value='';await load();ElMessage.success('表扬卡已发送')}
async function handleWarning(){await action('warning-handled','已联系学员并记录跟进')}
function focus(){if(focusRunning.value){clearInterval(timer);focusRunning.value=false;return}focusRunning.value=true;timer=setInterval(async()=>{if(--focusSeconds.value<=0){clearInterval(timer);focusRunning.value=false;focusSeconds.value=1500;await action('focus','完成25分钟专注')}},1000)}
function open(id){if(id==='focus')focus();else dialog.value=id}
onMounted(load);onBeforeUnmount(()=>clearInterval(timer))
</script>
<template><div class="page carex"><section class="carex-head"><div><p class="eyebrow">CARE & CONNECTION</p><h1>人文关怀</h1><p>关注状态，也关注每一次真实的师徒连接</p></div><div class="today-care"><span>今日关怀完成</span><b>{{completed}} / 4</b><el-progress :percentage="completed*25" :show-text="false" :stroke-width="7"/></div></section>
<section class="carex-grid"><article v-for="item in cards" :key="item.id" :class="`state-${item.state}`"><header><span class="carex-icon"><component :is="item.icon"/></span><em><CircleCheck v-if="item.state==='done'"/>{{item.status}}</em></header><div><h2>{{item.name}}</h2><p>{{item.desc}}</p></div><el-button :type="item.state==='alert'?'warning':item.state==='done'?'success':'primary'" :plain="item.state!=='active'" :icon="item.state==='done'?CircleCheck:ArrowRight" @click="open(item.id)">{{item.action}}</el-button></article></section>
<section class="chatx"><header><div><h2>师徒对话</h2><p>{{counterpart?.name}} · {{messages.length}} 条记录</p></div><el-select v-if="auth.user?.role==='mentor'" v-model="selectedUserId" @change="load"><el-option v-for="u in apprentices" :key="u.id" :label="u.name" :value="u.id"/></el-select></header><div class="chatx-history"><div v-for="m in messages" :key="m.id" :class="{mine:m.fromId===auth.user?.id}"><span>{{m.from.slice(0,1)}}</span><article><b>{{m.from}}</b><p>{{m.content}}</p><small>{{m.time}}</small></article></div><el-empty v-if="!messages.length" description="发送一句问候开始交流" :image-size="50"/></div><div class="quick"><button v-for="q in ['今天辛苦了，注意休息。','任务进展如何？有困难及时沟通。','收到，我会按计划完成。']" :key="q" @click="chatText=q">{{q}}</button></div><footer><el-input v-model="chatText" placeholder="输入问候、提醒或工作问题" @keyup.enter="sendMessage"/><el-button type="primary" @click="sendMessage">发送</el-button></footer></section>
<el-dialog v-model="dialog" :title="({daily:'每日关怀',health:'健康打卡',emotion:'情绪打卡',praise:'发送表扬卡',warning:'关怀提醒'})[dialog]" width="520"><div v-if="dialog==='daily'" class="dailyx"><b>今日关怀摘要</b><p>3项任务 · 14:00 导师辅导 · 午后注意天气变化</p><el-alert title="高温或降雨时减少连续户外作业，巡视注意防滑和防触电。" type="warning" :closable="false"/></div><div v-if="dialog==='health'" class="check-options"><div v-if="health" class="current"><CircleCheck/><span>当前状态：<b>{{health.value}}</b></span></div><button :class="{selected:health?.value==='状态良好'}" @click="action('health','状态良好')"><CircleCheck/><b>状态良好</b><small>精力充足，可以正常工作</small></button><button :class="{selected:health?.value==='需要关注'}" @click="action('health','需要关注')"><Bell/><b>需要关注</b><small>身体不适，需要适当调整</small></button></div><div v-if="dialog==='emotion'" class="mood-options"><div v-if="care.emotion" class="current"><CircleCheck/>今日已选择：{{care.emotion.mood}}</div><button v-for="item in moods" :key="item" :class="{selected:care.emotion?.mood===item}" :disabled="Boolean(care.emotion)" @click="mood(item)"><span>{{{开心:'悦',平静:'静',疲惫:'倦',焦虑:'忧',其他:'…'}[item]}}</span><b>{{item}}</b></button></div><div v-if="dialog==='praise'"><el-input v-model="praiseText" type="textarea" :rows="4" maxlength="200" show-word-limit placeholder="具体描述值得肯定的行为和成果"/><el-button type="primary" class="dialog-action" @click="sendPraise">发送给 {{counterpart?.name}}</el-button></div><div v-if="dialog==='warning'"><el-alert :title="warningDone?'今日提醒已处理':'赵六周报尚未提交'" :type="warningDone?'success':'warning'" show-icon :closable="false"/><p>先了解任务阻碍和当前状态，再共同确认补交时间。</p><el-button v-if="!warningDone" type="warning" @click="handleWarning">标记已联系并处理</el-button></div></el-dialog></div></template>
<style scoped>
.carex-head{display:flex;justify-content:space-between;align-items:end;margin-bottom:15px}.carex-head h1{margin:2px 0;font-size:27px}.carex-head>div>p:last-child{margin:0;color:#738092}.today-care{width:240px;background:#fff;border:1px solid #e0e7e5;padding:12px 14px}.today-care span{font-size:11px;color:#788595}.today-care b{float:right}.today-care .el-progress{clear:both;padding-top:8px}.carex-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.carex-grid article{background:#fff;border:1px solid #e1e7eb;border-top:3px solid #94a7a2;padding:16px;min-height:185px;display:flex;flex-direction:column;transition:.2s}.carex-grid article:hover{transform:translateY(-2px);box-shadow:0 8px 22px rgba(32,61,55,.09)}.carex-grid article.state-done{border-top-color:#087c66;background:linear-gradient(180deg,#f4faf8 0,#fff 45%)}.carex-grid article.state-alert{border-top-color:#d99023;background:linear-gradient(180deg,#fff9ed 0,#fff 45%)}.carex-grid article.state-active{border-top-color:#3378b8}.carex-grid header{display:flex;justify-content:space-between;align-items:center}.carex-icon{display:grid;place-items:center;width:38px;height:38px;background:#edf3f1;color:#087c66;border-radius:50%}.carex-icon svg{width:20px}.carex-grid em{display:flex;align-items:center;gap:4px;font-style:normal;font-size:10px;color:#687687;background:#f0f3f5;padding:4px 7px;border-radius:10px}.carex-grid em svg{width:12px}.carex-grid h2{font-size:16px;margin:16px 0 6px}.carex-grid p{font-size:12px;line-height:1.6;color:#687687;margin:0 0 14px}.carex-grid .el-button{margin-top:auto;width:100%}.chatx{background:#fff;border:1px solid #e1e7eb;margin-top:14px;padding:18px}.chatx>header{display:flex;justify-content:space-between}.chatx h2{font-size:17px;margin:0}.chatx header p{font-size:11px;color:#7e8a99}.chatx-history{height:260px;overflow:auto;background:#f7f9fa;padding:12px}.chatx-history>div{display:flex;gap:8px;margin:9px 0}.chatx-history>div.mine{flex-direction:row-reverse}.chatx-history>div>span{display:grid;place-items:center;width:29px;height:29px;border-radius:50%;background:#087c66;color:#fff}.chatx-history article{max-width:70%;background:#fff;padding:8px 10px;border-radius:5px}.chatx-history .mine article{background:#e7f4f0}.chatx-history p{margin:4px 0;font-size:12px}.chatx-history small{color:#8d98a6;font-size:9px}.quick{display:flex;gap:6px;flex-wrap:wrap;margin:9px 0}.quick button{border:1px solid #dfe5e8;background:#fff;padding:5px 8px;font-size:10px;cursor:pointer}.chatx footer{display:flex;gap:8px}.check-options{display:grid;grid-template-columns:1fr 1fr;gap:10px}.check-options .current,.mood-options .current{grid-column:1/-1;display:flex;gap:7px;align-items:center;background:#eaf6f2;color:#087c66;padding:10px}.check-options .current svg{width:17px}.check-options button{display:grid;grid-template-columns:24px 1fr;text-align:left;gap:3px;border:1px solid #dfe5e8;background:#fff;padding:14px;cursor:pointer}.check-options button svg{grid-row:1/3;width:20px;color:#087c66}.check-options button small{color:#7d8997}.check-options button.selected{border:2px solid #087c66;background:#f0f8f6}.mood-options{display:flex;gap:8px;flex-wrap:wrap}.mood-options button{width:76px;border:1px solid #dfe5e8;background:#fff;padding:10px;cursor:pointer}.mood-options button span,.mood-options button b{display:block}.mood-options button span{font-size:20px;color:#087c66}.mood-options button.selected{border:2px solid #087c66;background:#eaf6f2}.dialog-action{width:100%;margin-top:12px}@media(max-width:900px){.carex-grid{grid-template-columns:1fr 1fr}}@media(max-width:580px){.carex-grid{grid-template-columns:1fr}.today-care{display:none}.check-options{grid-template-columns:1fr}}
</style>

